 "content": "def transform(grid):
    # Marked cells (2,8) rise upwards as vertical stems; a 2 also tops its column.
    out=[r[:] for r in grid]
    r=next(i for i,row in enumerate(grid) if any(v in (2,8) for v in row))
    for c,v in enumerate(grid[r]):
        if v in (2,8):
            for rr in range(max(0,r-4),r):
                out[rr][c]=1
            if v==2 and r>=5:
                out[r-4][c]=2
            elif v==8 and r>=5:
                out[r-4][c]=8
    return out
